-- STEP 18.11 — Integration verification
-- Expected result: 40 / 40 PASS before GitHub/Netlify deployment.
with checks(check_no,check_name,status,details) as (
 select 1,'integration_contract_table',case when to_regclass('public.accounting_integration_contracts') is not null then 'PASS' else 'FAIL' end,'Canonical event-contract registry exists.'
 union all select 2,'expected_financial_events_view',case when to_regclass('public.accounting_expected_financial_events') is not null then 'PASS' else 'FAIL' end,'Source-fact coverage view exists.'
 union all select 3,'integration_health_rpc',case when to_regprocedure('public.accounting_integration_health()') is not null then 'PASS' else 'FAIL' end,'Integration health RPC exists.'
 union all select 4,'integration_exceptions_rpc',case when to_regprocedure('public.accounting_integration_exceptions(integer)') is not null then 'PASS' else 'FAIL' end,'Exception-detail RPC exists.'
 union all select 5,'active_contract_count',case when (select count(*) from public.accounting_integration_contracts where active)=27 then 'PASS' else 'FAIL' end,'Expected 27 active contracts.'
 union all select 6,'financial_contract_count',case when (select count(*) from public.accounting_integration_contracts where active and route='FINANCIAL_OUTBOX')=22 then 'PASS' else 'FAIL' end,'Expected 22 STEP 17 financial routes.'
 union all select 7,'domain_contract_count',case when (select count(*) from public.accounting_integration_contracts where active and route='DOMAIN_EVENT_ONLY')=5 then 'PASS' else 'FAIL' end,'Expected 5 compliance domain-only routes.'
 union all select 8,'all_contract_source_tables_exist',case when not exists(select 1 from public.accounting_integration_contracts c where c.active and to_regclass('public.'||c.source_table) is null) then 'PASS' else 'FAIL' end,'Every registered source table resolves.'
 union all select 9,'all_registered_producers_exist',case when not exists(select 1 from public.accounting_integration_contracts c where c.active and ((c.producer_kind='TRIGGER' and not exists(select 1 from pg_trigger t where t.tgname=c.producer_name and not t.tgisinternal)) or (c.producer_kind='RPC' and not exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname=c.producer_name)))) then 'PASS' else 'FAIL' end,'Every trigger/RPC producer exists.'
 union all select 10,'all_rule_contracts_configured',case when not exists(select 1 from public.accounting_integration_contracts c where c.active and c.route='FINANCIAL_OUTBOX' and c.posting_mode='RULE' and not exists(select 1 from public.accounting_posting_rules r where r.source_system='PLEASE' and r.event_type=c.event_type and r.enabled)) then 'PASS' else 'FAIL' end,'Every RULE route has an enabled posting rule.'
 union all select 11,'period_close_custom_posting',case when exists(select 1 from public.accounting_integration_contracts where event_type='PERIOD_CLOSE_ADJUSTMENT_POSTED' and posting_mode='CUSTOM' and route='FINANCIAL_OUTBOX') then 'PASS' else 'FAIL' end,'Period-close lines remain custom controlled posting.'
 union all select 12,'credit_note_priority',case when exists(select 1 from public.accounting_integration_contracts where event_type='CREDIT_NOTE_ISSUED' and priority=20 and dependency_event_type='INVOICE_ISSUED') then 'PASS' else 'FAIL' end,'Credit note follows invoice in worker ordering.'
 union all select 13,'refund_priority',case when exists(select 1 from public.accounting_integration_contracts where event_type='REFUND_COMPLETED' and priority=30 and dependency_event_type='CREDIT_NOTE_ISSUED') then 'PASS' else 'FAIL' end,'Refund follows credit note in worker ordering.'
 union all select 14,'stripe_fee_dependency',case when exists(select 1 from public.accounting_integration_contracts where event_type='STRIPE_FEE_RECORDED' and dependency_event_type='PAYMENT_RECEIVED' and priority=40) then 'PASS' else 'FAIL' end,'Stripe fee follows payment.'
 union all select 15,'supplier_payment_dependency',case when exists(select 1 from public.accounting_integration_contracts where event_type='SUPPLIER_PAYMENT_PAID' and dependency_event_type='VENDOR_BILL_POSTED') then 'PASS' else 'FAIL' end,'Supplier payment dependency is registered.'
 union all select 16,'payroll_payment_dependency',case when exists(select 1 from public.accounting_integration_contracts where event_type='PAYROLL_PAID' and dependency_event_type='PAYROLL_POSTED') then 'PASS' else 'FAIL' end,'Payroll pay follows payroll post.'
 union all select 17,'outbox_contract_guard_trigger',case when exists(select 1 from pg_trigger where tgname='trg_step18_11_outbox_contract_guard' and not tgisinternal) then 'PASS' else 'FAIL' end,'Outbox rejects unregistered/misrouted financial types.'
 union all select 18,'gifi_domain_trigger',case when exists(select 1 from pg_trigger where tgname='trg_step18_11_gifi_domain_event' and not tgisinternal) then 'PASS' else 'FAIL' end,'GIFI creation is domain-event only.'
 union all select 19,'obligation_domain_trigger',case when exists(select 1 from pg_trigger where tgname='trg_step18_11_obligation_domain_event' and not tgisinternal) then 'PASS' else 'FAIL' end,'Compliance obligation creation is domain-event only.'
 union all select 20,'approval_domain_trigger',case when exists(select 1 from pg_trigger where tgname='trg_step18_11_approval_domain_event' and not tgisinternal) then 'PASS' else 'FAIL' end,'Compliance approvals are domain-event only.'
 union all select 21,'evidence_domain_trigger',case when exists(select 1 from pg_trigger where tgname='trg_step18_11_evidence_domain_event' and not tgisinternal) then 'PASS' else 'FAIL' end,'Filing/payment evidence is domain-event only.'
 union all select 22,'package_domain_trigger',case when exists(select 1 from pg_trigger where tgname='trg_step18_11_package_domain_event' and not tgisinternal) then 'PASS' else 'FAIL' end,'Accountant package creation is domain-event only.'
 union all select 23,'compliance_routes_never_financial',case when not exists(select 1 from public.accounting_integration_contracts where domain='Compliance' and (route<>'DOMAIN_EVENT_ONLY' or posting_mode<>'NONE')) then 'PASS' else 'FAIL' end,'Compliance contracts cannot create journals.'
 union all select 24,'contract_rls_enabled',case when exists(select 1 from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname='public' and c.relname='accounting_integration_contracts' and c.relrowsecurity) then 'PASS' else 'FAIL' end,'RLS is enabled on contract registry.'
 union all select 25,'no_unregistered_existing_outbox',case when not exists(select 1 from public.please_accounting_outbox o where upper(coalesce(o.source_system,'PLEASE'))='PLEASE' and not exists(select 1 from public.accounting_integration_contracts c where c.event_type=o.event_type and c.active and c.route='FINANCIAL_OUTBOX')) then 'PASS' else 'FAIL' end,'Every existing PLEASE outbox type is registered.'
 union all select 26,'no_existing_source_mismatch',case when not exists(select 1 from public.please_accounting_outbox o join public.accounting_integration_contracts c on c.event_type=o.event_type and c.active and c.route='FINANCIAL_OUTBOX' where coalesce(o.source_table,'')<>c.source_table) then 'PASS' else 'FAIL' end,'Existing outbox rows match source-table contracts.'
 union all select 27,'no_missing_durable_events',case when not exists(select 1 from public.accounting_expected_financial_events e left join public.please_accounting_outbox o on o.event_key=e.event_key where o.id is null) then 'PASS' else 'FAIL' end,'Every current financial source fact has its durable event.'
 union all select 28,'no_dead_letter',case when not exists(select 1 from public.please_accounting_outbox where status='DEAD_LETTER') then 'PASS' else 'FAIL' end,'No exhausted accounting event.'
 union all select 29,'posted_events_have_external_event',case when not exists(select 1 from public.please_accounting_outbox where status='POSTED' and cal_event_id is null) then 'PASS' else 'FAIL' end,'POSTED outbox rows link to CAL external events.'
 union all select 30,'posted_events_have_journal',case when not exists(select 1 from public.please_accounting_outbox where status='POSTED' and cal_journal_entry_id is null) then 'PASS' else 'FAIL' end,'POSTED outbox rows link to journals.'
 union all select 31,'posted_journals_are_posted',case when not exists(select 1 from public.please_accounting_outbox o left join public.accounting_journal_entries j on j.id=o.cal_journal_entry_id where o.status='POSTED' and (j.id is null or j.status<>'POSTED')) then 'PASS' else 'FAIL' end,'Linked journals are immutable POSTED journals.'
 union all select 32,'ignored_events_have_no_journal',case when not exists(select 1 from public.please_accounting_outbox where status='IGNORED' and cal_journal_entry_id is not null) then 'PASS' else 'FAIL' end,'IGNORED events never create journals.'
 union all select 33,'expected_event_keys_unique',case when (select count(*) from public.accounting_expected_financial_events)=(select count(distinct event_key) from public.accounting_expected_financial_events) then 'PASS' else 'FAIL' end,'One expected event key per financial source fact.'
 union all select 34,'domain_events_not_in_outbox',case when not exists(select 1 from public.please_accounting_outbox where event_type in ('GIFI_WORKING_PAPER_CREATED','COMPLIANCE_OBLIGATION_CREATED','COMPLIANCE_APPROVAL_RECORDED','COMPLIANCE_EVIDENCE_RECORDED','ACCOUNTANT_PACKAGE_CREATED')) then 'PASS' else 'FAIL' end,'Compliance domain events never enter financial outbox.'
 union all select 35,'invoice_trigger_present',case when exists(select 1 from pg_trigger where tgname='trg_step17_accounting_invoice_event' and not tgisinternal) then 'PASS' else 'FAIL' end,'PLEASE invoice producer remains attached.'
 union all select 36,'payment_trigger_present',case when exists(select 1 from pg_trigger where tgname='trg_step17_accounting_payment_event' and not tgisinternal) then 'PASS' else 'FAIL' end,'PLEASE payment/Stripe producer remains attached.'
 union all select 37,'provider_trigger_present',case when exists(select 1 from pg_trigger where tgname='trg_step17_accounting_provider_payment_event' and not tgisinternal) then 'PASS' else 'FAIL' end,'PLEASE provider-payment producer remains attached.'
 union all select 38,'integration_health_callable',case when jsonb_typeof(public.accounting_integration_health())='object' then 'PASS' else 'FAIL' end,'Health RPC returns JSON object.'
 union all select 39,'integration_exception_contract_clean',case when not exists(select 1 from public.accounting_integration_exceptions(5000) where issue_code in ('SOURCE_TABLE_MISSING','PRODUCER_MISSING','POSTING_RULE_MISSING','UNREGISTERED_OUTBOX_EVENT','SOURCE_CONTRACT_MISMATCH')) then 'PASS' else 'FAIL' end,'No structural integration blocker.'
 union all select 40,'step18_11_ready',case when (public.accounting_integration_health()->>'blockers')::int=0 then 'PASS' else 'FAIL' end,'Cross-module integration currently has zero BLOCKER exceptions.'
)
select * from checks order by check_no;
